// Deterministic, anonymized username: salted SHA-256 hash of the email.
// Set at user-insert time via wp_pre_insert_user_data so WordPress writes the
// exact value with no slug-uniqueness suffix (-2). One mechanism, at the source.
add_filter( 'wp_pre_insert_user_data', 'cashaadi_set_hashed_username', 10, 4 );
function cashaadi_set_hashed_username( $data, $update, $user_id, $userdata ) {

	// Only act on brand-new user creation, never on profile updates or existing users.
	if ( $update ) {
		return $data;
	}

	// Require an email to derive the deterministic slug; otherwise leave WP defaults.
	if ( empty( $data['user_email'] ) ) {
		return $data;
	}

	// Same email always yields the same handle; salted so it is not a plain email hash.
	$hash   = substr( hash( 'sha256', strtolower( trim( $data['user_email'] ) ) . wp_salt() ), 0, 12 );
	$handle = 'user_' . $hash;

	$data['user_login']    = $handle;
	$data['user_nicename'] = $handle;

	return $data;
}
