function exclude_admins_and_current_loggedin_user_from_members_directory( $args ) {
    if ( bp_is_members_directory() ) {
        $exclude_ids = array();

        // Exclude administrators
        $admin_users = get_users( array(
            'role'   => 'Administrator',
            'fields' => 'ID'
        ) );
        if ( ! empty( $admin_users ) ) {
            $exclude_ids = array_merge( $exclude_ids, $admin_users );
        }

        // Exclude currently logged-in user
        if ( is_user_logged_in() ) {
            $exclude_ids[] = get_current_user_id();
        }

        // Merge with existing exclude array if necessary
        if ( ! empty( $exclude_ids ) ) {
            $args['exclude'] = ! empty( $args['exclude'] )
                ? array_merge( (array) $args['exclude'], $exclude_ids )
                : $exclude_ids;
        }
    }
    return $args;
}
add_filter( 'bp_after_has_members_parse_args', 'exclude_admins_and_current_loggedin_user_from_members_directory' );

/**
 * Members Directory filter
 * – hide admins + self
 * – show only opposite‑gender members for non‑admin users
 *
 * Works on bp_pre_user_query_construct which lets us
 * change the underlying BP_User_Query before it runs.
 */
add_action( 'bp_pre_user_query_construct', function ( BP_User_Query $query ) {
    
	/* -------------------------------------------------------------
	 * 0. Run only on the main Members directory
	 * ----------------------------------------------------------- */
	if ( ! bp_is_members_directory() ) {
		return;                       // widgets / profile tabs etc. unaffected
	}
	
	/* -------------------------------------------------------------
	 * 1. Always exclude admins and the current visitor
	 * ----------------------------------------------------------- */
	$exclude = isset( $query->query_vars['exclude'] )
		? (array) $query->query_vars['exclude']
		: array();

	// a) administrators
	$admin_ids = get_users( array(
		'role'   => 'administrator',
		'fields' => 'ids',
	) );
	$exclude = array_merge( $exclude, $admin_ids );

	// b) the logged‑in user (if any)
	if ( is_user_logged_in() ) {
		$exclude[] = bp_loggedin_user_id();
	}

	$query->query_vars['exclude'] = array_unique( array_map( 'intval', $exclude ) );


	/* -------------------------------------------------------------
	 * 2. Opposite‑gender filter (skip for admins & guests)
	 * ----------------------------------------------------------- */
	if ( ! is_user_logged_in() || current_user_can( 'administrator' ) ) {
		return;                       // no gender filter for admins/guests
	}
	
	$has_cur_user_profile_incomplete = ! csm_user_profile_is_complete( get_current_user_id() );
    if( $has_cur_user_profile_incomplete ) {
        // if current logged in user profile is incomplete then show all members on directory page
        return;   
    }
	
	// 2.1 get the visitor’s gender
	$current_gender = xprofile_get_field_data( 'Gender', bp_loggedin_user_id() );
	
	if ( ! $current_gender ) {
		return;                       // gender not set ➜ show everyone
	}

	$current_gender = strtolower( $current_gender );
	$want_gender = '';
	if( 'male' === $current_gender ) {
	    $want_gender = 'Female';
	} else if( 'female' === $current_gender ) {
	    $want_gender = 'Male';
	}

	if ( ! $want_gender ) {
		return;                       // unknown value ➜ show everyone
	}

	// 2.2 add an xprofile_query clause
	$xprofile_query   = $query->query_vars['xprofile_query'] ?? array();
	$xprofile_query[] = array(
		'field'   => 'Gender',       // use field *name* or numeric ID
		'value'   => $want_gender,
		'compare' => '=',
	);

	$query->query_vars['xprofile_query'] = $xprofile_query;
}, 20 );


