// if user has incomplete profile and trying to access the other user profile then redirect to current loggedin user to his/her profile instead of other user
// Returns true only if a REQUIRED xProfile field is empty for the given user.
// Gate logic is based on mandatory (required) fields only, NOT the display-only completion meter.
function cashaadi_has_missing_required_fields( $user_id ) {
    if ( ! $user_id || ! function_exists( 'bp_xprofile_get_groups' ) ) {
        return false;
    }
	// Require a profile photo (avatar) as part of completion.
	if ( function_exists( 'bp_get_user_has_avatar' ) && ! bp_get_user_has_avatar( $user_id ) ) {
		return true; // missing profile photo => incomplete
	}

    $groups = bp_xprofile_get_groups( array(
        'fetch_fields'      => true,
        'fetch_field_data'  => false,
        'hide_empty_fields' => false,
    ) );
    foreach ( $groups as $group ) {
        if ( empty( $group->fields ) ) {
            continue;
        }
        foreach ( $group->fields as $field ) {
            if ( empty( $field->is_required ) ) {
                continue; // only enforce required fields
            }
            $value = xprofile_get_field_data( $field->id, $user_id );
            if ( $value === '' || $value === null || ( is_array( $value ) && count( $value ) === 0 ) ) {
                return true; // a required field is empty -> incomplete
            }
        }
    }
    return false;
}

