/**
 * Flag: Hide exact "last active" time everywhere. Show only a coarse
 * "Active today" indicator (active within the last 24h) or nothing.
 * Profile headers use bp_get_last_activity; member loops use bp_member_last_active.
 */
function cashaadi_coarse_last_active( $string ) {
    $user_id = 0;
    if ( function_exists( 'bp_get_member_user_id' ) && bp_get_member_user_id() ) {
        $user_id = bp_get_member_user_id();
    } elseif ( function_exists( 'bp_displayed_user_id' ) && bp_displayed_user_id() ) {
        $user_id = bp_displayed_user_id();
    }
    if ( ! $user_id || ! function_exists( 'bp_get_user_last_activity' ) ) {
        return '';
    }
    $last = bp_get_user_last_activity( $user_id );
    if ( empty( $last ) ) {
        return '';
    }
    $ts = strtotime( $last );
    if ( $ts && ( time() - $ts ) < DAY_IN_SECONDS ) {
        return __( 'Active today', 'buddyx-child' );
    }
    return '';
}
add_filter( 'bp_get_last_activity', 'cashaadi_coarse_last_active', 99 );
add_filter( 'bp_member_last_active', 'cashaadi_coarse_last_active', 99 );
